import{H as e,Q as t,ht as n,it as r,nt as i,rt as a,tt as o,yt as s}from"./chunks/framework.DGYbyS8e.js";var c=JSON.parse(`{"title":"HighOrderMRI.jl overview","description":"","frontmatter":{},"headers":[],"relativePath":"concepts-overview.md","filePath":"concepts-overview.md","lastUpdated":1787724520000}`),l={name:`concepts-overview.md`};function u(e,c,l,u,d,f){let p=s(`VitePressMermaid`);return n(),o(`div`,null,[c[0]||=t(`h1`,{id:`highordermri-jl-overview`,tabindex:`-1`},[a(`HighOrderMRI.jl overview `),t(`a`,{class:`header-anchor`,href:`#highordermri-jl-overview`,"aria-label":`Permalink to “HighOrderMRI.jl overview”`},`​`)],-1),c[1]||=t(`p`,null,`HighOrderMRI.jl implements a field-aware MRI reconstruction framework in which the physical signal model is kept fixed while the numerical realization of the encoding operator can be changed according to the problem size and available hardware.`,-1),r(p,{code:`flowchart%20TD%0A%20%20%20%20A%5B%22Measured%20k-space%20data%22%5D%20--%3E%20G%5B%22Iterative%20reconstruction%22%5D%0A%20%20%20%20B%5B%22Measured%20or%20predicted%20dynamic%20fields%22%5D%20--%3E%20C%5B%22Synchronization%20%2B%20field%20preprocessing%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Expanded%20field-aware%20encoding%20model%22%5D%0A%0A%20%20%20%20D%20--%3E%20E1%5B%22HighOrderOp%22%5D%0A%20%20%20%20D%20--%3E%20E2%5B%22HighOrderKernelOp%22%5D%0A%20%20%20%20D%20--%3E%20E3%5B%22HighOrderLowRankOp%22%5D%0A%0A%20%20%20%20E1%20--%3E%20G%0A%20%20%20%20E2%20--%3E%20G%0A%20%20%20%20E3%20--%3E%20G%0A%20%20%20%20G%20--%3E%20H%5B%22Reconstructed%20image%22%5D`}),c[2]||=i(`<p>The three operators therefore differ in computational strategy rather than in the target physical model: <code>HighOrderOp</code> evaluates the expanded encoding explicitly, <code>HighOrderKernelOp</code> performs the same explicit calculation with fused CUDA kernels, and <code>HighOrderLowRankOp</code> introduces a controlled approximation of the residual spatial phase term.</p><h2 id="core-components" tabindex="-1">Core components <a class="header-anchor" href="#core-components" aria-label="Permalink to “Core components”">​</a></h2><h3 id="dynamic-field-encoding" tabindex="-1">Dynamic field encoding <a class="header-anchor" href="#dynamic-field-encoding" aria-label="Permalink to “Dynamic field encoding”">​</a></h3><p>The encoding model combines Cartesian or non-Cartesian sampling, receive-coil sensitivities, static off-resonance, and spatially varying dynamic field terms. The current high-order encoding constructors support real solid-harmonic terms through third order.</p><h3 id="explicit-implementations" tabindex="-1">Explicit implementations <a class="header-anchor" href="#explicit-implementations" aria-label="Permalink to “Explicit implementations”">​</a></h3><p><code>HighOrderOp</code> provides the array-based explicit implementation, whereas <code>HighOrderKernelOp</code> evaluates the same model using fused CUDA kernels and supported multi-GPU execution. Agreement between these implementations assesses numerical consistency of the software pathways; it is not, by itself, an independent validation of the underlying physical model.</p><h3 id="low-rank-acceleration" tabindex="-1">Low-rank acceleration <a class="header-anchor" href="#low-rank-acceleration" aria-label="Permalink to “Low-rank acceleration”">​</a></h3><p><code>HighOrderLowRankOp</code> accelerates repeated forward and adjoint evaluations using per-dynamic randomized SVD followed by an adaptive spatial basis shared across dynamics. The approximation is restricted to the residual spatial phase representation; first-order Fourier encoding remains in the NFFT. The factorization and coefficient conventions are derived in <a href="/HighOrderMRI.jl/dev/theory/low-rank">Low-rank shared subspace</a>.</p><h3 id="validation-strategy" tabindex="-1">Validation strategy <a class="header-anchor" href="#validation-strategy" aria-label="Permalink to “Validation strategy”">​</a></h3><p>Validation is organized hierarchically. Explicit-implementation agreement, low-rank approximation error, independent numerical validation, and physical validation address distinct questions and should be reported separately. The <a href="/HighOrderMRI.jl/dev/guide/validation">scientific validation strategy</a> defines these evidence levels, and the <a href="/HighOrderMRI.jl/dev/guide/reconstruction-protocol">reconstruction protocol</a> specifies the conventions that should remain fixed during controlled comparisons.</p>`,10)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};